let inputSource = 'manual';
let source;

try {
  source = $('Get row(s)1').first().json;
  inputSource = 'queue';
} catch {
  source = $('テーマ入力フォーム').first().json;
}

const result = {
  ...source,
  source: inputSource,
  row_id: inputSource === 'queue' ? source.id : null,
  improvement_guidance: ''
};
const keys = ['hook', 'duration', 'caption_density', 'scene_changes', 'narration', 'cta', 'topic_selection'];
try {
  const response = $input.first().json;
  if (response.statusCode && response.statusCode !== 200) throw new Error('HTTP status');
  const payload = response.body?.data ?? response.body ?? response.data;
  const feedback = typeof payload === 'string' ? JSON.parse(payload) : payload;
  const actions = feedback?.improvement_actions;
  if (feedback?.status !== 'ready' || !actions || typeof actions !== 'object' || Array.isArray(actions)) throw new Error('Invalid feedback');
  if (!keys.every(key => Object.prototype.hasOwnProperty.call(actions, key) && typeof actions[key] === 'string' && actions[key].trim().length > 0 && actions[key].length <= 240 && !/[\r\n\x00-\x1f]/.test(actions[key]))) throw new Error('Invalid actions');
  result.improvement_guidance = keys.map(key => key + ': ' + actions[key].trim()).join('\n');
} catch (_) {
  // An unavailable or malformed improvement must not block normal script generation.
}
return [{ json: result }];

